#include <iostream>
#include <vector>
#include <string>
#include <queue>
#include <algorithm>
#include <functional>
#include <utility>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long n;
    long long k;
    cin >> n >> k;
    vector<long long> speed(n);
    for (int i = 0; i < n; i++) cin >> speed[i];
    vector<long long> eff(n);
    for (int i = 0; i < n; i++) cin >> eff[i];

    vector<pair<long long, long long>> team;
    for (int i = 0; i < n; i++) team.push_back({eff[i], speed[i]});
    sort(team.begin(), team.end(), greater<pair<long long, long long>>());
    priority_queue<long long, vector<long long>, greater<long long>> heap;
    long long total = 0, best = 0;
    for (const auto& member : team) {
        heap.push(member.second);
        total += member.second;
        if ((long long)heap.size() > k) {
            total -= heap.top();
            heap.pop();
        }
        best = max(best, total * member.first);
    }
    cout << best << "\n";

    return 0;
}

