import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer tokens = new StringTokenizer("");

    static String next() throws IOException {
        while (!tokens.hasMoreTokens()) {
            tokens = new StringTokenizer(in.readLine());
        }
        return tokens.nextToken();
    }

    public static void main(String[] args) throws IOException {
        long n = Long.parseLong(next());
        long k = Long.parseLong(next());
        long[] speed = new long[(int) n];
        for (int i = 0; i < speed.length; i++) speed[i] = Long.parseLong(next());
        long[] eff = new long[(int) n];
        for (int i = 0; i < eff.length; i++) eff[i] = Long.parseLong(next());

        int count = (int) n;
        long[][] team = new long[count][];
        for (int i = 0; i < count; i++) team[i] = new long[] {eff[i], speed[i]};
        Arrays.sort(team, (p, q) -> p[0] != q[0] ? Long.compare(q[0], p[0]) : Long.compare(q[1], p[1]));
        PriorityQueue<Long> heap = new PriorityQueue<>();
        long total = 0, best = 0;
        for (long[] member : team) {
            heap.add(member[1]);
            total += member[1];
            if (heap.size() > k) total -= heap.poll();
            best = Math.max(best, total * member[0]);
        }
        System.out.println(best);
    }
}
